{"name":"list_dir","description":"List a directory","parameters":{"type":"object","properties":{"path":{"type":"string"}},"required":["path"]}}
{"name":"run_tests","description":"Run the project test suite","parameters":{"type":"object","properties":{"filter":{"type":"string"}},"required":[]}}
{"name":"grep","description":"Search file contents by regex","parameters":{"type":"object","properties":{"pattern":{"type":"string"},"path":{"type":"string"}},"required":["pattern"]}}
{"name":"edit","description":"Replace a string in a file","parameters":{"type":"object","properties":{"path":{"type":"string"},"old":{"type":"string"},"new":{"type":"string"}},"required":["path","old","new"]}}
